// Íconos del sistema como emojis de color (más visuales y fáciles de entender).
// Vite reemplaza "lucide-react" por este archivo (vite.config.js): los íconos de
// contenido (secciones, pestañas, indicadores, categorías) se dibujan con su emoji;
// los controles (flechas, cerrar, más, buscar, editar, borrar…) siguen como línea.
import { createElement, forwardRef } from "react";
export * from "lucide-react/dist/esm/lucide-react.js";

// Tamaño del emoji según el ancho del ícono (w-4, w-3.5, w-[1.1em]…) o la prop size
const tam = (clase = "", size) => {
  const a = /(?:^|\s)w-\[([\d.]+)(px|rem|em)\]/.exec(clase);
  if (a) return `${(Number(a[1]) * 0.86).toFixed(3)}${a[2]}`;
  const b = /(?:^|\s)w-([\d.]+)(?:\s|$)/.exec(clase);
  if (b) return `${(Number(b[1]) * 0.25 * 0.86).toFixed(3)}rem`;
  return `${Math.round((Number(size) || 20) * 0.86)}px`;
};
const conEmoji = (emoji, nombre) => {
  const C = forwardRef(({ className = "", size, style, strokeWidth, absoluteStrokeWidth, color, fill, ...resto }, ref) =>
    createElement("span", { ref, role: "img", "aria-hidden": true, ...resto, className: `rd-emoji rd-emoji-icono ${className}`, style: { fontSize: tam(className, size), ...style } }, emoji),
  );
  C.displayName = nombre;
  return C;
};

